#!/usr/bin/env bash
# 2026-10-15: SA2 LEC on RTL 6c4ccffd, pass 2 again. Pass 1 (results/lec_sa2_6c4c_20261015/p1) completed every step; the
# first pass 2 died in its front end when the WSL VM shut down at 2026-10-15T05:00Z (kept as
# p2_failed_wsl_vm_shutdown_20261015T0500Z). The fresh p2 holds scripts regenerated by prepare_lec_6c4c.py, checked
# byte-identical to p1's. Steps as run_lec_6c4c_goldn1.sh: p2 GoldN1, A, Mul, Inv, NegFSM, xsens; then the xsens negative
# control in p1 and compare_lec_vc4_goldn1.py --no-negalign. Memory gate 8 GB per step (PD shares the WSL VM).
set -u
R=/e/Projects/RISCV-research
LEC='E:/Projects/RISCV-research/asic/equiv/lec'
PY='/c/Users/toanl/AppData/Local/Programs/Python/Python311/python.exe'
LOG=$R/results/lec_6c4c_20261015_chain.log
L=$R/results/lec_sa2_6c4c_20261015
WL='E:\Projects\RISCV-research\results\lec_sa2_6c4c_20261015'
say () { echo "$(date -u +%FT%TZ) $*" | tee -a $LOG; }
memwait () { until [ "$(MSYS_NO_PATHCONV=1 wsl.exe -d Ubuntu -e bash -c "free -m | awk '/Mem/{print \$7}'" 2>/dev/null | tr -dc 0-9)" -ge 8000 ] 2>/dev/null; do sleep 60; done; }
run () {
    local log=$1; shift
    memwait
    pwsh -NoProfile -File "$@" > "$log" 2>&1
    local rc=$?
    say "lec_sa2_6c4c_20261015/$(basename $(dirname $log))/$(basename $log) exit $rc"
    [ $rc -eq 0 ] || { say "STOP: $(basename $log) failed"; tail -5 "$log" | tee -a $LOG; exit 1; }
}
say "sa2 pass 2 again (RTL 6c4ccffd; the first p2 died in the WSL VM shutdown)"
run $L/p2/frontend_goldn1.out "$LEC/run_frontends_vc4.ps1" -Work "$WL\\p2" -Part GoldN1
for s in A Mul Inv NegFSM; do run $L/p2/step$s.out "$LEC/run_lec_vc4.ps1" -Work "$WL\\p2" -Step $s; done
run $L/p2/xsens_main.out "$LEC/run_xsens.ps1" -Work "$WL\\p2" -Tag main
run $L/p1/xsens_neg.out "$LEC/run_xsens.ps1" -Work "$WL\\p1" -Neg
"$PY" -B "$R/asic/equiv/lec/compare_lec_vc4_goldn1.py" "$WL\\p1" "$WL\\p2" "$WL\\pass_comparison_goldn1.json" --no-negalign > $L/compare.out 2>&1
say "sa2 compare exit $?: $(tail -1 $L/compare.out)"
